perfSuite('Performance - IFilter', async function () {
    const uri = $hh.asBrowserUri('vs/base/test/common/filters.perf.data').toString(true);
    const { data } = await $AJ(uri, '');
    function perfTest(name, match) {
        test(name, () => {
            const t1 = Date.now();
            let count = 0;
            for (let i = 0; i < 2; i++) {
                for (const pattern of patterns) {
                    for (const item of data) {
                        count += 1;
                        match(pattern, item);
                    }
                }
            }
            const d = Date.now() - t1;
            console.log(name, `${d}ms, ${Math.round(count / d) * 15}/15ms, ${Math.round(count / d)}/1ms`);
        });
    }
    perfTest('matchesFuzzy', filters.$Ul);
    perfTest('matchesFuzzy2', filters.$Vl);
    perfTest('matchesPrefix', filters.$Ol);
    perfTest('matchesContiguousSubString', filters.$Pl);
    perfTest('matchesCamelCase', filters.$Sl);
});
